import React, { useEffect } from "react";
import { useSelector, useDispatch } from "react-redux";
import { fetchUser } from "../Features/UserSlice";
import { useNavigate } from "react-router-dom";
import "../Styles/UserProfile.css";

const UserProfile = () => {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const { user, isLoading, isError } = useSelector((state) => state.users);

  // Protection: redirect if not logged in
  useEffect(() => {
    const role = localStorage.getItem("role");
    if (!role) navigate("/login");
  }, [navigate]);

  useEffect(() => {
    const email =
      user?.email || JSON.parse(localStorage.getItem("loggedUser"))?.email;
    if (email) dispatch(fetchUser(email));
  }, [dispatch]);

  if (isLoading) return <p>Loading user info...</p>;
  if (isError) return <p>Error loading profile</p>;
  if (!user) return <p>No user found.</p>;

  return (
    <div className="profile-page">
      <div className="profile-card">
        <div className="profile-left">
          <div className="profile-icon">👤</div>
          <div>
            <h2 className="profile-name">{user.name}</h2>
            <p className="profile-email">{user.email}</p>
            <p className="profile-detail">
              {user.major} • Age: {user.age} • {user.role}
            </p>
          </div>
        </div>
      </div>

      <div className="history-box">
        <h3>My Applications</h3>
        <p>Feature coming soon — applications will show here.</p>
      </div>
    </div>
  );
};

export default UserProfile;
